import java.util.Scanner;

public class Main {
    static long[] a = new long[20];

    static long solve(long n) {
        if (n == 0) {
            return 0;
        }
        int ind = 0;
        for (int i = 1; i <= 16; i++) {
            if (a[i] > n) {
                ind = i;
                break;
            }
        }
        long ans1 = (long) 1e18;
        long ans2 = (long) 1e18;
        ans1 = (n / a[ind - 1]) * (ind - 1) + solve(n % a[ind - 1]);
        if (a[ind] - n < n) {
            ans2 = ind + solve(a[ind] - n);
        }
        return Math.min(ans1, ans2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        a[0] = 0;
        for (int i = 1; i <= 16; i++) {
            a[i] = a[i - 1] * 10 + 1;
        }
        long n = scanner.nextLong();
        System.out.println(solve(n));
        scanner.close();
    }
}
